<?php
require_once __DIR__.'/../config/database.php';
function money($amount) { return '₹'.number_format((float)$amount,2); }$pageTitle='Track Your Payment';$base='../';$records=[];$error=null;$searched=false;
if(isset($_GET['ivrs'])){$searched=true;$ivrs=trim((string)$_GET['ivrs']);if(!preg_match('/^[0-9]{5,20}$/',$ivrs))$error='Enter a valid numeric IVRS.';else try{$q=$pdo->prepare("SELECT p.transaction_ref,p.paid_amount,p.discount_amount,p.status,p.paid_at,b.bill_month FROM payments p JOIN bills b ON b.id=p.bill_id JOIN consumers c ON c.id=b.consumer_id WHERE c.ivrs_no=? ORDER BY p.id DESC LIMIT 20");$q->execute([$ivrs]);$records=$q->fetchAll();}catch(Throwable $ex){$error='Database unavailable. Check PostgreSQL configuration.';}}
include '../includes/header.php';?>
<a href="../index.php">← Back to Home</a><section class="hero"><div class="eyebrow">Module 04 · Database Connected</div><h1>Track Your Payment</h1><p>Search by IVRS to see payment history. Receipt generation comes in the payment phase.</p></section>
<div class="panel"><form method="get"><label class="form-label fw-bold" for="ivrs">Consumer IVRS Number</label><div class="input-group"><input class="form-control" id="ivrs" name="ivrs" value="<?=htmlspecialchars($_GET['ivrs']??'')?>" placeholder="Enter IVRS number" required><button class="btn btn-brand">Search Payment</button></div></form>
<?php if($error):?><div class="alert alert-danger mt-3"><?=htmlspecialchars($error)?></div><?php elseif($searched):?><div class="table-responsive mt-4"><table class="table"><thead><tr><th>Transaction</th><th>Bill Month</th><th>Discount</th><th>Amount</th><th>Status</th><th>Paid At</th><th>Receipt</th></tr></thead><tbody><?php foreach($records as $r):?><tr><td><?=htmlspecialchars($r['transaction_ref'])?></td><td><?=htmlspecialchars($r['bill_month'])?></td><td><?=money($r['discount_amount'])?></td><td><?=money($r['paid_amount'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars($r['paid_at']??'—')?></td><td><?php if($r['status']==='SUCCESS'):?><a href="receipt.php?ref=<?=urlencode($r['transaction_ref'])?>" target="_blank">PDF Receipt</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$records):?><p class="muted">No payment transactions found for this IVRS yet.</p><?php endif;?></div><?php endif;?></div>
